func (s *Service) Available(ctx context.Context) (available bool, err error) {
	err = s.run(ctx, "availability", func(txCtx context.Context) (domain.OperationStats, error) {
		available, err = s.settings.MealPlanEnabled(txCtx)
		return domain.OperationStats{}, err
	})
	return available, err
}

func (r OrderingRules) ParentRegistrationUntil(day Date) time.Time {
	deadline := r.RegistrationAt(day)
	if r.Model == ModelAnnual && r.AnnualDeadline != "" {
		if annual := r.AnnualDeadline.EndOfDay(); annual.Before(deadline) {
			return annual
		}
	}
	return deadline
}
